import React, { useState } from 'react';
import PiePagina from '../Componentes/PiePagina';

const mascotas = [
  {
    id: 1,
    nombre: 'Toby',
    especie: 'Perro',
    tamano: 'Mediano',
    edad: '2 años',
    etapa: 'Adulto',
    energia: 'Alta',
    personalidad: 'Juguetón, alegre y cariñoso. Le encanta compartir momentos con las personas.',
    foto: 'https://images.unsplash.com/photo-1552053831-71594a27632d?w=700'
  },
  {
    id: 2,
    nombre: 'Luna',
    especie: 'Gato',
    tamano: 'Pequeño',
    edad: '8 meses',
    etapa: 'Cachorro',
    energia: 'Media',
    personalidad: 'Curiosa, tranquila y compañera. Disfruta de los espacios cómodos y los mimos.',
    foto: 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=700'
  },
  {
    id: 3,
    nombre: 'Max',
    especie: 'Perro',
    tamano: 'Grande',
    edad: '3 años',
    etapa: 'Adulto',
    energia: 'Alta',
    personalidad: 'Activo, inteligente y fiel. Ideal para compartir paseos y juegos.',
    foto: 'https://images.unsplash.com/photo-1537151608828-ea2b11777ee8?w=700'
  },
  {
    id: 4,
    nombre: 'Mia',
    especie: 'Gato',
    tamano: 'Pequeño',
    edad: '1 año',
    etapa: 'Joven',
    energia: 'Media',
    personalidad: 'Dulce y sociable. Le gusta descansar y recibir cariño.',
    foto: 'https://images.unsplash.com/photo-1573865526739-10659fec78a5?w=700'
  },
  {
    id: 5,
    nombre: 'Rocky',
    especie: 'Perro',
    tamano: 'Grande',
    edad: '5 años',
    etapa: 'Adulto',
    energia: 'Media',
    personalidad: 'Noble, protector y compañero. Disfruta de la tranquilidad.',
    foto: 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=700'
  },
  {
    id: 6,
    nombre: 'Nina',
    especie: 'Gato',
    tamano: 'Pequeño',
    edad: '4 meses',
    etapa: 'Cachorro',
    energia: 'Alta',
    personalidad: 'Juguetona, curiosa y muy cariñosa. Busca una familia que la cuide.',
    foto: 'https://images.unsplash.com/photo-1511044568932-338cba0ad803?w=700'
  }
];

function Servicios() {
  const [especie, setEspecie] = useState('Todas');
  const [tamano, setTamano] = useState('Todos');
  const [edad, setEdad] = useState('Todas');

  const mascotasFiltradas = mascotas.filter((mascota) => {
    return (
      (especie === 'Todas' || mascota.especie === especie) &&
      (tamano === 'Todos' || mascota.tamano === tamano) &&
      (edad === 'Todas' || mascota.etapa === edad)
    );
  });

  return (
    <div className="catalogo-huellitas">

      <style>{`
        .catalogo-huellitas {
          max-width: 1200px;
          margin: 0 auto;
          padding: 35px 20px;
          color: #333;
          font-family: Arial, sans-serif;
        }

        .catalogo-huellitas .catalogo-encabezado {
          text-align: center;
          margin-bottom: 30px;
        }

        .catalogo-huellitas h1 {
          color: #684b38;
          font-size: 32px;
          margin-bottom: 12px;
        }

        .catalogo-huellitas .catalogo-descripcion {
          color: #666;
          font-size: 16px;
          line-height: 1.6;
        }

        .catalogo-huellitas .filtros {
          display: flex;
          justify-content: center;
          flex-wrap: wrap;
          gap: 18px;
          margin: 25px 0;
        }

        .catalogo-huellitas .filtro {
          display: flex;
          flex-direction: column;
          gap: 7px;
          min-width: 160px;
        }

        .catalogo-huellitas .filtro label {
          font-weight: bold;
          color: #684b38;
        }

        .catalogo-huellitas .filtro select {
          padding: 11px;
          border: 1px solid #ccc;
          border-radius: 8px;
          background: white;
          font-size: 15px;
        }

        .catalogo-huellitas .cantidad {
          text-align: center;
          margin: 25px 0;
          color: #684b38;
          font-weight: bold;
        }

        .catalogo-huellitas .mascotas-grid {
          display: grid;
          grid-template-columns: repeat(
            auto-fit,
            minmax(250px, 1fr)
          );
          gap: 25px;
        }

        .catalogo-huellitas .mascota-card {
          background: white;
          border-radius: 12px;
          overflow: hidden;
          box-shadow: 0 3px 12px rgba(0,0,0,0.12);
          display: flex;
          flex-direction: column;
        }

        .catalogo-huellitas .foto-mascota {
          width: 100%;
          height: 230px;
          object-fit: cover;
          display: block;
          background: #f1eee9;
        }

        .catalogo-huellitas .foto-no-disponible {
          width: 100%;
          height: 230px;
          display: none;
          align-items: center;
          justify-content: center;
          background: #f1eee9;
          color: #684b38;
          font-size: 15px;
          text-align: center;
        }

        .catalogo-huellitas .mascota-contenido {
          padding: 18px;
          display: flex;
          flex-direction: column;
          flex: 1;
        }

        .catalogo-huellitas .mascota-contenido h2 {
          color: #684b38;
          margin: 0 0 8px;
        }

        .catalogo-huellitas .datos {
          color: #777;
          margin: 0 0 12px;
        }

        .catalogo-huellitas .personalidad {
          line-height: 1.5;
          flex: 1;
        }

        .catalogo-huellitas .boton-adoptar {
          display: block;
          text-align: center;
          text-decoration: none;
          color: white;
          background: #b87951;
          padding: 12px;
          border-radius: 8px;
          font-weight: bold;
          margin-top: 15px;
        }

        .catalogo-huellitas .boton-adoptar:hover {
          background: #8e5838;
        }

        .catalogo-huellitas .sin-resultados {
          text-align: center;
          padding: 35px;
          color: #777;
          grid-column: 1 / -1;
        }

        @media (max-width: 600px) {
          .catalogo-huellitas h1 {
            font-size: 25px;
          }

          .catalogo-huellitas .filtro {
            width: 100%;
          }
        }
      `}</style>

      <div className="catalogo-encabezado">
        <h1>Encontrá tu nueva compañía</h1>

        <p className="catalogo-descripcion">
          Conocé a nuestros perros y gatos que esperan una familia.
          ¡Uno de ellos puede ser tu nuevo mejor amigo!
        </p>
      </div>

      <div className="filtros">

        <div className="filtro">
          <label>Especie</label>

          <select
            value={especie}
            onChange={(e) => setEspecie(e.target.value)}
          >
            <option value="Todas">Todas</option>
            <option value="Perro">Perros</option>
            <option value="Gato">Gatos</option>
          </select>
        </div>

        <div className="filtro">
          <label>Tamaño</label>

          <select
            value={tamano}
            onChange={(e) => setTamano(e.target.value)}
          >
            <option value="Todos">Todos</option>
            <option value="Pequeño">Pequeño</option>
            <option value="Mediano">Mediano</option>
            <option value="Grande">Grande</option>
          </select>
        </div>

        <div className="filtro">
          <label>Edad</label>

          <select
            value={edad}
            onChange={(e) => setEdad(e.target.value)}
          >
            <option value="Todas">Todas</option>
            <option value="Cachorro">Cachorros</option>
            <option value="Joven">Jóvenes</option>
            <option value="Adulto">Adultos</option>
          </select>
        </div>

      </div>

      <p className="cantidad">
        Mascotas encontradas: {mascotasFiltradas.length}
      </p>

      <div className="mascotas-grid">

        {mascotasFiltradas.length > 0 ? (

          mascotasFiltradas.map((mascota) => (

            <article className="mascota-card" key={mascota.id}>

              <img
                className="foto-mascota"
                src={mascota.foto}
                alt={`Fotografía de ${mascota.nombre}`}
                onError={(e) => {
                  e.currentTarget.style.display = 'none';
                  e.currentTarget.nextElementSibling.style.display = 'flex';
                }}
              />

              <div className="foto-no-disponible">
                Fotografía no disponible
              </div>

              <div className="mascota-contenido">

                <h2>{mascota.nombre}</h2>

                <p className="datos">
                  {mascota.especie} · {mascota.tamano}
                </p>

                <p>
                  <strong>Edad:</strong> {mascota.edad}
                </p>

                <p>
                  <strong>Energía:</strong> {mascota.energia}
                </p>

                <p className="personalidad">
                  {mascota.personalidad}
                </p>

                <a
                  className="boton-adoptar"
                  href="/Contacto"
                >
                  Quiero adoptar a {mascota.nombre} ❤️
                </a>

              </div>

            </article>

          ))

        ) : (

          <div className="sin-resultados">
            No se encontraron mascotas con esos filtros.
          </div>

        )}

      </div>

      <PiePagina />

    </div>
  );
}

export default Servicios;
